#!/usr/bin/env python3
"""Pole label review tool - a tiny zero-dependency web app.

Shows each test image with candidate pole boxes:
  - human labels (yellow) start ACCEPTED
  - SAM 3 suggestions (cyan) start PENDING
The reviewer clicks boxes to toggle accept/reject, draws new boxes by dragging,
and the verified label set is saved server-side (JSON + exportable YOLO txt).

Run locally:   python app.py
Data files:    candidates.json (boxes), images/ (jpgs), reviews/ (output)
Persistence:   REVIEW_DATA_DIR env (default ./data) holds reviews.json.
"""
import os, io, json, base64, threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs
from pathlib import Path

ROOT = Path(__file__).parent
IMG_DIR = ROOT / "images"
CAND = ROOT / "candidates.json"
DATA_DIR = Path(os.environ.get("REVIEW_DATA_DIR", ROOT / "data"))
DATA_DIR.mkdir(parents=True, exist_ok=True)
REVIEWS = DATA_DIR / "reviews.json"
UPLOAD_DIR = DATA_DIR / "uploads"; UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
CAND_UP = DATA_DIR / "candidates_uploaded.json"   # user-uploaded stems (blind: no boxes)
RESULTS = DATA_DIR / "results.json"               # accuracy dashboard payload (posted by local compute)
WIRES = DATA_DIR / "wires.json"                   # wire polylines: {stem: [[[x,y],...], ...]}
_lock = threading.Lock()

# Live camera demo: single-slot latest-frame state (not a queue) so the
# GPU poller always works on the freshest frame and stale ones are dropped.
_live_lock = threading.Lock()
_live = {"frame_id": 0, "frame": b"", "result_id": 0, "boxes": []}

_baked = json.loads(CAND.read_text()) if CAND.exists() else {}
ACCESS_TOKEN = os.environ.get("REVIEW_TOKEN", "")  # if set, require ?t=TOKEN


def load_uploaded():
    return json.loads(CAND_UP.read_text()) if CAND_UP.exists() else {}


def all_candidates():
    c = dict(_baked); c.update(load_uploaded()); return c


def all_stems():
    # uploaded first (the active eval set), then any baked stems
    up = sorted(load_uploaded().keys())
    return up + [s for s in sorted(_baked.keys()) if s not in set(up)]


def load_reviews():
    if REVIEWS.exists():
        return json.loads(REVIEWS.read_text())
    return {}


def save_review(stem, boxes):
    with _lock:
        r = load_reviews()
        r[stem] = boxes
        REVIEWS.write_text(json.dumps(r))


def load_wires():
    return json.loads(WIRES.read_text()) if WIRES.exists() else {}


def save_wires(stem, lines):
    # lines: list of polylines, each a list of [x, y] points in natural image coords
    with _lock:
        w = load_wires()
        w[stem] = lines
        WIRES.write_text(json.dumps(w))


