class H(BaseHTTPRequestHandler):
    def _send(self, code, ctype, body):
        if isinstance(body, str):
            body = body.encode()
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    MAX_BODY = 25 * 1024 * 1024  # 25MB cap on any POST body (camera frames, JSON, uploads)

    def _read_body(self):
        n = int(self.headers.get("Content-Length", 0))
        if n > self.MAX_BODY:
            self._send(413, "text/plain", "payload too large")
            return None
        return self.rfile.read(n)

    def _authed(self):
        if not ACCESS_TOKEN:
            return True
        q = parse_qs(urlparse(self.path).query)
        if q.get("t", [""])[0] == ACCESS_TOKEN:
            return True
        c = self.headers.get("Cookie", "")
        return f"t={ACCESS_TOKEN}" in c

    def do_GET(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if u.path == "/healthz":
            return self._send(200, "text/plain", "ok")
        if not self._authed():
            return self._send(403, "text/plain", "forbidden: append ?t=YOUR_TOKEN to the URL")
        if u.path == "/" or u.path == "/index.html":
            # set token cookie so subsequent same-origin fetches pass
            body = INDEX_HTML.encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            if ACCESS_TOKEN:
                self.send_header("Set-Cookie", f"t={ACCESS_TOKEN}; Path=/; Max-Age=2592000; SameSite=Lax")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            return self.wfile.write(body)
        if u.path == "/upload":
            body = UPLOAD_HTML.encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            if ACCESS_TOKEN:
                self.send_header("Set-Cookie", f"t={ACCESS_TOKEN}; Path=/; Max-Age=2592000; SameSite=Lax")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            return self.wfile.write(body)
        if u.path == "/dashboard":
            return self._send(200, "text/html; charset=utf-8", DASH_HTML)
        if u.path == "/results":
            return self._send(200, "text/html; charset=utf-8", RESULTS_HTML)
        if u.path == "/live":
            body = LIVE_HTML.encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            if ACCESS_TOKEN:
                self.send_header("Set-Cookie", f"t={ACCESS_TOKEN}; Path=/; Max-Age=2592000; SameSite=Lax")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            return self.wfile.write(body)
        if u.path == "/wire":
            body = WIRE_HTML.encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            if ACCESS_TOKEN:
                self.send_header("Set-Cookie", f"t={ACCESS_TOKEN}; Path=/; Max-Age=2592000; SameSite=Lax")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            return self.wfile.write(body)
        if u.path == "/api/wire/stems":
            # only images pushed for wire tracing (wire_ prefix)
            ws = sorted(k for k in load_uploaded() if k.startswith("wire_"))
            return self._send(200, "application/json", json.dumps(ws))
        if u.path == "/api/wire/traced":
            return self._send(200, "application/json", json.dumps(sorted(load_wires().keys())))
        if u.path == "/api/wire/item":
            stem = q.get("stem", [""])[0]
            return self._send(200, "application/json",
                              json.dumps({"wires": load_wires().get(stem, [])}))
        if u.path == "/api/live/pending":
            with _live_lock:
                pend = _live["frame_id"] if _live["frame_id"] > _live["result_id"] else None
            return self._send(200, "application/json", json.dumps({"frame_id": pend}))
        if u.path == "/api/live/frame":
            with _live_lock:
                body = _live["frame"]
            return self._send(200, "image/jpeg", body)
        if u.path == "/api/live/result":
            with _live_lock:
                out = {"frame_id": _live["result_id"], "boxes": _live["boxes"]}
            return self._send(200, "application/json", json.dumps(out))
        if u.path == "/api/results":
            return self._send(200, "application/json",
                              RESULTS.read_text() if RESULTS.exists() else "{}")
        if u.path == "/api/uploaded":
            # stems the user uploaded (for the local compute step to pull + score)
            return self._send(200, "application/json", json.dumps(sorted(load_uploaded().keys())))
        if u.path == "/api/stems":
            return self._send(200, "application/json", json.dumps(all_stems()))
        if u.path == "/api/progress":
            stems = all_stems(); r = load_reviews()
            done = [s for s in stems if s in r]
            nxt = next((i for i, s in enumerate(stems) if s not in r), 0)
            return self._send(200, "application/json",
                              json.dumps({"done": len(done), "total": len(stems),
                                          "next": nxt, "done_list": list(r.keys())}))
        if u.path == "/api/item":
            stem = q.get("stem", [""])[0]
            c = all_candidates().get(stem, {})
            r = load_reviews().get(stem)
            boxes = []
            if r is not None:
                for b in r:
                    boxes.append({"src": b["src"], "state": "keep", "box": b["box"]})
            else:
                for b in c.get("human", []):
                    boxes.append({"src": "human", "state": "keep", "box": b[:4]})
                for b in c.get("sam3", []):
                    boxes.append({"src": "sam3", "state": "pending", "box": b[:4],
                                  "score": b[4] if len(b) > 4 else ""})
            return self._send(200, "application/json", json.dumps({"boxes": boxes}))
        if u.path.startswith("/img/"):
            name = os.path.basename(u.path)
            for d in (UPLOAD_DIR, IMG_DIR):   # uploaded first, then baked
                p = d / name
                if p.exists():
                    return self._send(200, "image/jpeg", p.read_bytes())
            return self._send(404, "text/plain", "no image")
        if u.path == "/api/export":
            return self._send(200, "application/json", json.dumps(load_reviews()))
        if u.path == "/healthz":
            return self._send(200, "text/plain", "ok")
        return self._send(404, "text/plain", "not found")

    def do_POST(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        if not self._authed():
            return self._send(403, "text/plain", "forbidden")
        if u.path == "/api/save":
            body = self._read_body()
            if body is None: return
            data = json.loads(body or b"{}")
            save_review(data["stem"], data.get("boxes", []))
            return self._send(200, "application/json", json.dumps({"ok": True}))
        if u.path == "/api/upload":
            # raw image bytes; ?name=&w=&h= (browser sends natural dims). Blind: no boxes.
            body = self._read_body()
            if body is None: return
            name = os.path.basename(q.get("name", ["img.jpg"])[0])
            stem = os.path.splitext(name)[0]
            W = int(q.get("w", ["0"])[0]); H = int(q.get("h", ["0"])[0])
            with _lock:
                (UPLOAD_DIR / f"{stem}.jpg").write_bytes(body)
                up = load_uploaded()
                up[stem] = {"w": W, "h": H, "human": [], "sam3": []}
                CAND_UP.write_text(json.dumps(up))
            return self._send(200, "application/json", json.dumps({"ok": True, "stem": stem}))
        if u.path == "/api/ingest":
            # local compute posts model predictions here -> shown as boxes for review.
            # body: {stem: [[x0,y0,x1,y1,conf],...], ...}
            body = self._read_body()
            if body is None: return
            preds = json.loads(body or b"{}")
            with _lock:
                up = load_uploaded()
                for stem, boxes in preds.items():
                    if stem in up:
                        up[stem]["sam3"] = boxes           # model auto-labels (cyan, editable)
                CAND_UP.write_text(json.dumps(up))
            return self._send(200, "application/json", json.dumps({"ok": True, "n": len(preds)}))
        if u.path == "/api/wire/save":
            body = self._read_body()
            if body is None: return
            data = json.loads(body or b"{}")
            save_wires(data["stem"], data.get("wires", []))
            return self._send(200, "application/json", json.dumps({"ok": True}))
        if u.path == "/api/live/upload":
            # raw jpg bytes from the browser's camera capture loop
            body = self._read_body()
            if body is None: return
            if not body.startswith(b"\xff\xd8"):
                return self._send(415, "text/plain", "expected jpeg")
            with _live_lock:
                _live["frame_id"] += 1
                _live["frame"] = body
                fid = _live["frame_id"]
            return self._send(200, "application/json", json.dumps({"frame_id": fid}))
        if u.path == "/api/live/result":
            # GPU poller posts back detections for a frame_id
            body = self._read_body()
            if body is None: return
            data = json.loads(body or b"{}")
            with _live_lock:
                if data.get("frame_id", -1) > _live["result_id"]:
                    _live["result_id"] = data["frame_id"]
                    _live["boxes"] = data.get("boxes", [])
            return self._send(200, "application/json", json.dumps({"ok": True}))
        if u.path == "/api/results":
            # local compute posts the accuracy payload here -> dashboard renders it
            body = self._read_body()
            if body is None: return
            RESULTS.write_text((body or b"").decode() or "{}")
            return self._send(200, "application/json", json.dumps({"ok": True}))
        if u.path == "/api/reset":
            with _lock:
                REVIEWS.write_text("{}")
                CAND_UP.write_text("{}")
                RESULTS.write_text("{}")
                for f in UPLOAD_DIR.glob("*.jpg"):
                    f.unlink()
            return self._send(200, "application/json", json.dumps({"ok": True, "reset": True}))
        return self._send(404, "text/plain", "not found")

    def log_message(self, *a):
        pass


def main():
    port = int(os.environ.get("PORT", 8080))
    srv = ThreadingHTTPServer(("0.0.0.0", port), H)
    print(f"Pole review tool on :{port}  ({len(all_stems())} images)")
    srv.serve_forever()


if __name__ == "__main__":
    main()
